<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowRight, Check, Clock3, LockKeyhole, Settings, Volume2, VolumeX, Wifi } from 'lucide-vue-next'
import { useAuthStore } from '../stores/auth.js'
import { useRoomStore } from '../stores/room.js'
import { lockRound, saveAnswers, stopRoundNow, watchMyAnswer, watchRound } from '../services/game.js'
import CharacterAvatar from '../components/common/CharacterAvatar.vue'
import { answerCompletion } from '../utils/completion.js'
import { audioManager } from '../audio/manager.js'
import { countdownCue } from '../audio/countdown.js'
import { syncRoomRoute } from '../utils/roomRoute.js'
import { useSettingsStore } from '../stores/settings.js'

const emit=defineEmits(['open-settings'])
const route=useRoute(),router=useRouter(),auth=useAuthStore(),roomStore=useRoomStore(),settings=useSettingsStore(); const round=ref(null),answers=reactive({}),now=ref(Date.now()),error=ref(''),confirmStop=ref(false),stopping=ref(false),saveState=ref('saved'),stopOverlay=ref(false),activeCategory=ref(0),answerInputs=ref([]);let stopRound,tick,saveTimer,previousSecond=null,completionWas=false,answerHydrated=false
const arabicNumber=new Intl.NumberFormat('ar-EG',{useGrouping:false})
const code=computed(()=>String(route.params.code).toUpperCase()),roundId=computed(()=>String(route.params.roundId));const remaining=computed(()=>Math.max(0,Math.ceil(((round.value?.deadline?.toMillis?.()||0)-now.value)/1000)));const formatted=computed(()=>`${arabicNumber.format(Math.floor(remaining.value/60)).padStart(2,'٠')}:${arabicNumber.format(remaining.value%60).padStart(2,'٠')}`);const urgent=computed(()=>remaining.value>0&&remaining.value<=10);let stopAnswer,locking=false,releaseRoom
const stoppingPlayer=computed(()=>roomStore.players.find(player=>player.uid===round.value?.stoppedBy))
const categories=computed(()=>roomStore.room?.categories||[]),completion=computed(()=>answerCompletion(categories.value,answers)),completionPercent=computed(()=>completion.value.total?completion.value.completed/completion.value.total*100:0)
onMounted(async()=>{await auth.initialize();releaseRoom=roomStore.subscribe(code.value);stopAnswer=watchMyAnswer(code.value,roundId.value,auth.uid,value=>{if(!answerHydrated&&value?.values)Object.assign(answers,value.values);completionWas=completion.value.isComplete;answerHydrated=true;if(completionWas)audioManager.mark(`complete:${code.value}:${roundId.value}:${auth.uid}`)},e=>error.value=e.message);stopRound=watchRound(code.value,roundId.value,value=>{round.value=value;if(value?.status==='answering'){const started=value.startedAt?.toMillis?.()||0;if(Date.now()-started<3000)audioManager.playOnce('roundStart',`round-start:${code.value}:${roundId.value}`)}else audioManager.stopTimer();if(value?.status==='reviewing'||value?.status==='finalized'){clearTimeout(saveTimer);if(value.stopReason==='harfana'){audioManager.playOnce('harfana',`harfana:${code.value}:${roundId.value}`);stopOverlay.value=true}}},e=>error.value=e.message);tick=setInterval(()=>now.value=Date.now(),500)})
onBeforeUnmount(()=>{releaseRoom?.();stopRound?.();stopAnswer?.();audioManager.stopTimer();clearInterval(tick);clearTimeout(saveTimer)})
watch(()=>roomStore.room,room=>syncRoomRoute(router,route.path,room,code.value),{deep:true})
watch(answers,()=>{answerHydrated=true;clearTimeout(saveTimer);if(round.value?.status==='answering'&&remaining.value>0){saveState.value='saving';saveTimer=setTimeout(async()=>{try{await saveAnswers(code.value,roundId.value,auth.uid,{...answers});saveState.value='saved'}catch(e){saveState.value='error';error.value=e.message}},500)}},{deep:true})
watch(remaining,async value=>{const cue=countdownCue({previous:previousSecond,current:value,status:round.value?.status,visible:!document.hidden});previousSecond=value;if(cue)audioManager.playOnce(cue,`timer:${code.value}:${roundId.value}:${value}`);if(value===0&&round.value?.status==='answering'&&!locking){locking=true;try{await lockRound(code.value,roundId.value)}catch(e){if(!String(e.message).includes('failed-precondition'))error.value=e.message}finally{locking=false}}})
watch(()=>completion.value.isComplete,value=>{if(answerHydrated&&value&&!completionWas)audioManager.playOnce('complete',`complete:${code.value}:${roundId.value}:${auth.uid}`);completionWas=value})
function focusCategory(index){activeCategory.value=Math.max(0,Math.min(index,categories.value.length-1));requestAnimationFrame(()=>answerInputs.value[activeCategory.value]?.focus())}
function nextCategory(index){if(index<categories.value.length-1)focusCategory(index+1)}
function toggleMute(){settings.muted=!settings.muted;if(!settings.muted)audioManager.play('select',{force:true})}
function openStopConfirm(){if(!completion.value.isComplete){focusCategory(categories.value.indexOf(completion.value.missing[0]));return}confirmStop.value=true}
async function confirmHarfana(){if(!completion.value.isComplete){confirmStop.value=false;focusCategory(categories.value.indexOf(completion.value.missing[0]));return}clearTimeout(saveTimer);confirmStop.value=false;stopping.value=true;error.value='';try{await stopRoundNow(code.value,roundId.value,{...answers});saveState.value='saved'}catch(e){error.value=e?.message||'معرفناش نقفل الجولة.'}finally{stopping.value=false}}
</script>
<template><div class="game-demo"><header v-if="round" class="game-command-center" :class="{urgent}"><div class="game-command-bar"><RouterLink :to="`/room/${code}`" class="game-exit"><ArrowRight/><span>الخروج</span></RouterLink><div class="game-round-count"><small>الجولة</small><b>{{arabicNumber.format(round.number||1)}} <i>/ {{arabicNumber.format(roomStore.room?.totalRounds||0)}}</i></b></div><div class="game-timer" role="timer" :aria-label="`الوقت المتبقي ${formatted}`"><Clock3/><div><small>{{urgent?'الوقت بيخلص!':'الوقت المتبقي'}}</small><b dir="ltr">{{ formatted }}</b></div></div><div class="game-connection"><i></i><Wifi/><span>متصل</span></div><div class="game-tools"><button type="button" data-audio="none" :aria-label="settings.muted?'شغّل الصوت':'اقفل الصوت'" @click="toggleMute"><VolumeX v-if="settings.muted"/><Volume2 v-else/></button><button type="button" aria-label="إعدادات اللعبة" @click="emit('open-settings')"><Settings/></button></div></div><div class="game-round-focus"><div class="game-letter-badge"><small>حرف الجولة</small><b>{{round.letter}}</b></div><div class="game-round-copy"><span>الجولة {{arabicNumber.format(round.number||1)}}</span><h1>{{remaining?'اكتب أسرع ما عندك.. بس خليك حرفنجي!':'الأقلام اترفعت!'}}</h1><div class="game-answer-progress"><div class="game-progress-copy"><span>إجاباتك</span><b>{{arabicNumber.format(completion.completed)}} من {{arabicNumber.format(completion.total)}}</b></div><div class="game-progress-track" role="progressbar" :aria-valuenow="completion.completed" aria-valuemin="0" :aria-valuemax="completion.total"><i :style="{width:`${completionPercent}%`}"></i></div><small v-if="completion.missing.length">باقي {{arabicNumber.format(completion.missing.length)}} إجابة</small><small v-else class="complete-copy"><Check/> الكشكول كامل</small></div></div><div class="game-save-status save-pill" :class="saveState"><i></i>{{saveState==='saving'?'بنحفظ...':saveState==='error'?'الحفظ وقف':'الإجابات محفوظة'}}</div></div></header><main class="notebook-wrap"><section class="player-status-strip"><article v-for="player in roomStore.players" :key="player.uid" :class="{me:player.uid===auth.uid}"><CharacterAvatar :id="player.avatar" :size="38"/><span>{{player.nickname}}</span><i :class="{online:player.connected}"></i><small v-if="player.uid===auth.uid">{{completion.completed}}/{{completion.total}}</small></article></section><section class="notebook"><div class="spiral"><i v-for="n in 11" :key="n"/></div><nav class="mobile-category-nav"><button v-for="(category,index) in categories" :key="category" :class="{active:activeCategory===index,done:!completion.missing.includes(category)}" @click="focusCategory(index)">{{index+1}}</button></nav><div v-if="round?.status==='answering'&&remaining" class="live-answer-grid"><label v-for="(category,index) in categories" :key="category" :class="[`color-border-${index%4}`,{incomplete:completion.missing.includes(category),'mobile-active':activeCategory===index}]"><span>{{ category }}</span><input :ref="el=>answerInputs[index]=el" v-model="answers[category]" maxlength="80" :placeholder="`اكتب ${category} بحرف ${round.letter}`" @focus="activeCategory=index" @keydown.enter.prevent="nextCategory(index)"/></label><label class="total-preview"><span>المجموع</span><output>—</output><small>بعد التصحيح</small></label></div><div v-else class="round-locked"><LockKeyhole/><h2>الجولة اتقفلت</h2><p>استنى الأدمن يراجع الكراسات.</p></div><p v-if="error" class="error-message">{{ error }}</p></section><aside v-if="roomStore.room?.instantStopEnabled!==false&&round?.status==='answering'&&remaining" class="harfana-action" :class="{unlocked:completion.isComplete}"><div><b>{{completion.isComplete?'كله تمام.. جاهز؟':'كمّل الكشكول الأول'}}</b><span>{{completion.isComplete?'اقفل الجولة عند الكل!':`لسه ${completion.missing.length} إجابة ناقصة`}}</span></div><button :disabled="stopping||!completion.isComplete" @click="openStopConfirm">{{stopping?'بنقفل...':'حرفنة!'}}</button><small>{{completion.isComplete?'آخر تعديلاتك هتتحفظ لحظة القفل':'المجموع مش بيتحسب ضمن الإجابات'}}</small></aside></main>
<Transition name="fade"><div v-if="confirmStop" class="modal-backdrop" @click.self="confirmStop=false"><section class="modal-card stop-confirm"><span class="stop-pencil">✏️</span><h2>متأكد إنك خلصت؟</h2><p>الجولة هتقفل عند كل اللاعبين فورًا!</p><div><button class="btn btn-primary" @click="confirmHarfana">أيوه، حرفنة!</button><button class="btn btn-soft" @click="confirmStop=false">لسه بكتب</button></div></section></div></Transition>
<Transition name="fade"><div v-if="stopOverlay" class="stop-overlay"><div class="confetti-bits"><i v-for="n in 12" :key="n"/></div><span class="flying-pencil">✏️</span><h2>حرفنة!</h2><CharacterAvatar :id="stoppingPlayer?.avatar" :size="86"/><p><b>{{stoppingPlayer?.nickname||'حد من الحرفنجية'}}</b> خلّص الأول وقفّل الجولة!</p></div></Transition></div></template>
